css:
.tc{position:absolute;left:16px;top:16px;width:328px;height:88px;box-sizing:border-box;padding:16px;background-color:#1C1C1C;border:1px solid #4B5563;border-radius:12px;font-family:Inter, Roboto, sans-serif}
.tc [data-part=dot]{position:absolute;left:16px;top:16px;width:8px;height:8px;border-radius:50%}
.tc [data-part=name]{position:absolute;left:32px;top:10px;color:#F8F9FA;font-size:15px;font-weight:700;letter-spacing:1px;white-space:nowrap}
.tc [data-part=tier]{position:absolute;left:16px;top:44px;color:#8A8D93;font-family:"Roboto Mono", monospace;font-size:12px;white-space:nowrap}
.tc [data-part=dot]{background-color:#4B5563}
.tc [data-part=countdown]{position:absolute;right:16px;top:30px;color:#F8F9FA;font-family:"Roboto Mono", monospace;font-size:15px;font-weight:500}
